"""Read-only Feishu Wiki evidence collection helpers.

This module intentionally contains no FDE business decisions or Bitable access.
"""

import argparse
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
import os
from collections.abc import Callable, Mapping
from pathlib import Path
from tempfile import TemporaryDirectory
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.parse import parse_qsl, quote, urlencode, urlparse
from urllib.request import Request, urlopen


OPEN_FEISHU_ORIGIN = "https://open.feishu.cn"
TOKEN_PATH = "/open-apis/auth/v3/tenant_access_token/internal/"
WIKI_NODE_PATH = "/open-apis/wiki/v2/spaces/get_node"
DOCUMENT_PATH_PREFIX = "/open-apis/docx/v1/documents/"
ALLOWED_PATH_PREFIXES = (TOKEN_PATH, WIKI_NODE_PATH, DOCUMENT_PATH_PREFIX)
IP_ALLOWLIST_CODES = frozenset({99991401})
RATE_LIMIT_CODES = frozenset({99991400})
RESOURCE_ACCESS_CODES = frozenset({131006, 1770032, 99991663})
TRANSIENT_CODES = frozenset({131001})
CONTENT_TOO_LARGE_CODES = frozenset({1770033})
MANIFEST_SCHEMA_VERSION = "fde-feishu-wiki-evidence-v1"
MANIFEST_FIELDS = frozenset(
    {
        "schema_version",
        "title",
        "revision_id",
        "retrieved_at",
        "raw_sha256",
        "blocks_sha256",
        "representation",
        "manifest_sha256",
    }
)


@dataclass(frozen=True)
class ApiResponse:
    """One parsed HTTP response from the limited Feishu transport boundary."""

    status: int
    payload: Mapping[str, Any]


Transport = Callable[
    [str, str, Mapping[str, str] | None, bytes | None], ApiResponse
]
CredentialProvider = Callable[[], tuple[str, str]]


class EvidenceError(RuntimeError):
    """A deterministic, non-secret error emitted by the evidence adapter."""

    def __init__(self, code: str, detail: str = "") -> None:
        super().__init__(f"{code}:{detail}" if detail else code)
        self.code = code


def parse_wiki_url(value: str) -> str:
    """Return the node token from one canonical https Feishu Wiki URL."""
    parsed = urlparse(value)
    parts = [part for part in parsed.path.split("/") if part]
    if (
        parsed.scheme != "https"
        or not parsed.hostname
        or not parsed.hostname.endswith(".feishu.cn")
    ):
        raise EvidenceError("INVALID_WIKI_URL")
    if len(parts) != 2 or parts[0] != "wiki" or not parts[1]:
        raise EvidenceError("INVALID_WIKI_URL")
    return parts[1]


def parse_docx_url(value: str) -> str:
    """Return the document token from one canonical https Feishu docx URL."""
    parsed = urlparse(value)
    parts = [part for part in parsed.path.split("/") if part]
    if (
        parsed.scheme != "https"
        or not parsed.hostname
        or not parsed.hostname.endswith(".feishu.cn")
    ):
        raise EvidenceError("INVALID_DOCX_URL")
    if len(parts) != 2 or parts[0] != "docx" or not parts[1]:
        raise EvidenceError("INVALID_DOCX_URL")
    return parts[1]


def _is_direct_docx_url(value: str) -> bool:
    return urlparse(value).path.startswith("/docx/")


def require_credentials(environ: Mapping[str, str]) -> tuple[str, str]:
    """Read an app identity without exposing either value in errors or output."""
    app_id = environ.get("FEISHU_APP_ID") or environ.get("LARK_APP_ID")
    app_secret = environ.get("FEISHU_APP_SECRET") or environ.get("LARK_APP_SECRET")
    if not app_id or not app_secret:
        raise EvidenceError("CREDENTIALS_UNAVAILABLE")
    return app_id, app_secret


def _environment_credentials() -> tuple[str, str]:
    return require_credentials(os.environ)


def _require_mapping(value: object) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise EvidenceError("API_RESPONSE_INVALID")
    return value


def _assert_allowed_url(method: str, url: str) -> None:
    parsed = urlparse(url)
    if parsed.scheme != "https" or parsed.netloc != "open.feishu.cn":
        raise EvidenceError("ENDPOINT_REJECTED")
    query_pairs = parse_qsl(parsed.query, keep_blank_values=True)
    if method == "POST" and parsed.path == TOKEN_PATH and not query_pairs:
        return
    if (
        method == "GET"
        and parsed.path == WIKI_NODE_PATH
        and len(query_pairs) == 1
        and query_pairs[0][0] == "token"
        and query_pairs[0][1]
    ):
        return
    if method != "GET" or not parsed.path.startswith(DOCUMENT_PATH_PREFIX):
        raise EvidenceError("ENDPOINT_REJECTED")
    document_path = parsed.path.removeprefix(DOCUMENT_PATH_PREFIX)
    segments = document_path.split("/")
    if len(segments) == 1 and segments[0] and not query_pairs:
        return
    if (
        len(segments) == 2
        and segments[0]
        and segments[1] == "raw_content"
        and not query_pairs
    ):
        return
    if len(segments) != 2 or not segments[0] or segments[1] != "blocks":
        raise EvidenceError("ENDPOINT_REJECTED")
    parameters = dict(query_pairs)
    if (
        len(parameters) != len(query_pairs)
        or set(parameters) not in ({"document_revision_id", "page_size"}, {"document_revision_id", "page_size", "page_token"})
        or not parameters["document_revision_id"].isdecimal()
        or parameters["page_size"] != "100"
        or ("page_token" in parameters and not parameters["page_token"])
    ):
        raise EvidenceError("ENDPOINT_REJECTED")


def _decode_payload(raw: bytes, status: int) -> Mapping[str, Any]:
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        if status >= 400:
            return {}
        raise EvidenceError("API_RESPONSE_INVALID") from None
    return _require_mapping(payload)


def standard_transport(
    method: str,
    url: str,
    headers: Mapping[str, str] | None = None,
    body: bytes | None = None,
) -> ApiResponse:
    """Send a request only to the explicit read-only Feishu endpoint allowlist."""
    _assert_allowed_url(method, url)
    request = Request(url, data=body, headers=dict(headers or {}), method=method)
    try:
        with urlopen(request, timeout=15) as response:
            status = response.status
            raw = response.read()
    except HTTPError as error:
        status = error.code
        raw = error.read()
    except (TimeoutError, URLError):
        raise EvidenceError("TRANSIENT_FAILURE") from None
    return ApiResponse(status=status, payload=_decode_payload(raw, status))


def _raise_for_api_failure(response: ApiResponse) -> None:
    payload = _require_mapping(response.payload)
    code = payload.get("code")
    if response.status < 400 and code == 0:
        return
    if code in IP_ALLOWLIST_CODES:
        raise EvidenceError("IP_ALLOWLIST_DENIED")
    if response.status == 429 or code in RATE_LIMIT_CODES:
        raise EvidenceError("RATE_LIMITED")
    if response.status >= 500 or code in TRANSIENT_CODES:
        raise EvidenceError("TRANSIENT_FAILURE")
    if response.status in {401, 403, 404} or code in RESOURCE_ACCESS_CODES:
        raise EvidenceError("RESOURCE_ACCESS_DENIED")
    if code in CONTENT_TOO_LARGE_CODES:
        raise EvidenceError("CONTENT_TOO_LARGE")
    raise EvidenceError("API_REQUEST_FAILED")


def _request_json(
    transport: Transport,
    method: str,
    url: str,
    headers: Mapping[str, str] | None = None,
    body: bytes | None = None,
) -> Mapping[str, Any]:
    _assert_allowed_url(method, url)
    response = transport(method, url, headers, body)
    if not isinstance(response, ApiResponse):
        raise EvidenceError("TRANSPORT_PROTOCOL_ERROR")
    _raise_for_api_failure(response)
    return _require_mapping(response.payload)


def _tenant_access_token(
    credential_provider: CredentialProvider, transport: Transport
) -> str:
    app_id, app_secret = credential_provider()
    if not app_id or not app_secret:
        raise EvidenceError("CREDENTIALS_UNAVAILABLE")
    body = json.dumps(
        {"app_id": app_id, "app_secret": app_secret}, separators=(",", ":")
    ).encode("utf-8")
    payload = _request_json(
        transport,
        "POST",
        f"{OPEN_FEISHU_ORIGIN}{TOKEN_PATH}",
        {"Content-Type": "application/json; charset=utf-8"},
        body,
    )
    token = payload.get("tenant_access_token")
    if not isinstance(token, str) or not token:
        raise EvidenceError("CREDENTIALS_REJECTED")
    return token


def _document_metadata_url(document_id: str) -> str:
    return f"{OPEN_FEISHU_ORIGIN}{DOCUMENT_PATH_PREFIX}{quote(document_id, safe='')}"


def _document_metadata(
    transport: Transport, headers: Mapping[str, str], document_id: str
) -> tuple[str, int]:
    document_payload = _request_json(
        transport, "GET", _document_metadata_url(document_id), headers
    )
    document = _require_mapping(
        _require_mapping(document_payload.get("data")).get("document")
    )
    title = document.get("title")
    revision_id = document.get("revision_id")
    if (
        not isinstance(title, str)
        or not title
        or not isinstance(revision_id, int)
        or isinstance(revision_id, bool)
    ):
        raise EvidenceError("API_RESPONSE_INVALID")
    return title, revision_id


def _resolve_docx(
    source_url: str, credential_provider: CredentialProvider, transport: Transport
) -> tuple[Mapping[str, str], str, str, int]:
    access_token = _tenant_access_token(credential_provider, transport)
    headers = {"Authorization": f"Bearer {access_token}"}
    if _is_direct_docx_url(source_url):
        document_id = parse_docx_url(source_url)
        title, revision_id = _document_metadata(transport, headers, document_id)
        return headers, document_id, title, revision_id

    wiki_token = parse_wiki_url(source_url)
    node_payload = _request_json(
        transport,
        "GET",
        f"{OPEN_FEISHU_ORIGIN}{WIKI_NODE_PATH}?{urlencode({'token': wiki_token})}",
        headers,
    )
    node = _require_mapping(_require_mapping(node_payload.get("data")).get("node"))
    if node.get("obj_type") != "docx":
        raise EvidenceError("UNSUPPORTED_OBJECT_TYPE")
    document_id = node.get("obj_token")
    if not isinstance(document_id, str) or not document_id:
        raise EvidenceError("API_RESPONSE_INVALID")
    title, revision_id = _document_metadata(transport, headers, document_id)
    return headers, document_id, title, revision_id


def probe(
    source_url: str,
    *,
    credential_provider: CredentialProvider | None = None,
    transport: Transport | None = None,
) -> dict[str, str | int]:
    """Resolve a canonical Wiki or docx URL to metadata without reading content."""
    wiki_token = None
    if not _is_direct_docx_url(source_url):
        wiki_token = parse_wiki_url(source_url)
    use_credentials = credential_provider or _environment_credentials
    use_transport = transport or standard_transport
    _, document_id, title, revision_id = _resolve_docx(
        source_url, use_credentials, use_transport
    )
    result: dict[str, str | int] = {
        "title": title,
        "revision_id": revision_id,
        "document_id": document_id,
    }
    if wiki_token is not None:
        result["wiki_token"] = wiki_token
    return result


def reject_repository_output(output_dir: Path, repository_root: Path) -> None:
    """Prevent raw source evidence from being written into the Git repository."""
    resolved_output = output_dir.resolve()
    resolved_root = repository_root.resolve()
    if resolved_output == resolved_root or resolved_root in resolved_output.parents:
        raise EvidenceError("OUTPUT_PATH_REJECTED")


def _repository_root_from_module() -> Path | None:
    module_path = Path(__file__).resolve()
    for candidate in (module_path.parent, *module_path.parents):
        if (candidate / ".git").exists():
            return candidate
    return None


def _raw_content(
    transport: Transport, headers: Mapping[str, str], document_id: str
) -> str:
    payload = _request_json(
        transport, "GET", f"{_document_metadata_url(document_id)}/raw_content", headers
    )
    content = _require_mapping(payload.get("data")).get("content")
    if not isinstance(content, str):
        raise EvidenceError("API_RESPONSE_INVALID")
    if not content.strip():
        raise EvidenceError("CONTENT_EMPTY")
    return content


def _blocks_url(document_id: str, revision_id: int, page_token: str | None) -> str:
    parameters: list[tuple[str, str]] = [
        ("document_revision_id", str(revision_id)),
        ("page_size", "100"),
    ]
    if page_token is not None:
        parameters.append(("page_token", page_token))
    return f"{_document_metadata_url(document_id)}/blocks?{urlencode(parameters)}"


def _blocks(
    transport: Transport,
    headers: Mapping[str, str],
    document_id: str,
    revision_id: int,
) -> list[Mapping[str, Any]]:
    blocks: list[Mapping[str, Any]] = []
    page_token: str | None = None
    seen_page_tokens: set[str] = set()
    while True:
        payload = _request_json(
            transport,
            "GET",
            _blocks_url(document_id, revision_id, page_token),
            headers,
        )
        data = _require_mapping(payload.get("data"))
        items = data.get("items")
        has_more = data.get("has_more")
        if (
            not isinstance(items, list)
            or not all(isinstance(item, Mapping) for item in items)
            or not isinstance(has_more, bool)
        ):
            raise EvidenceError("BLOCKS_INVALID")
        blocks.extend(items)
        if not has_more:
            return blocks
        next_page_token = data.get("page_token")
        if (
            not isinstance(next_page_token, str)
            or not next_page_token
            or next_page_token in seen_page_tokens
        ):
            raise EvidenceError("BLOCKS_INVALID")
        seen_page_tokens.add(next_page_token)
        page_token = next_page_token


def _canonical_json_bytes(value: object) -> bytes:
    try:
        return json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError):
        raise EvidenceError("API_RESPONSE_INVALID") from None


def _sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _write_capture(
    output_dir: Path,
    raw_content: str,
    blocks: list[Mapping[str, Any]],
    manifest: Mapping[str, Any],
) -> None:
    if output_dir.exists() and (not output_dir.is_dir() or any(output_dir.iterdir())):
        raise EvidenceError("OUTPUT_PATH_NOT_EMPTY")
    output_dir.parent.mkdir(parents=True, exist_ok=True)
    if output_dir.exists():
        output_dir.rmdir()
    artifacts = {
        "raw_content.txt": raw_content.encode("utf-8"),
        "blocks.json": _canonical_json_bytes(blocks),
        "manifest.json": _canonical_json_bytes(manifest),
    }
    with TemporaryDirectory(dir=output_dir.parent) as temporary_directory:
        temporary_path = Path(temporary_directory)
        staged_capture = temporary_path / "capture"
        staged_capture.mkdir()
        for filename, content in artifacts.items():
            staged_file = staged_capture / filename
            staged_file.write_bytes(content)
        staged_capture.replace(output_dir)


def capture(
    wiki_url: str,
    output_dir: Path,
    *,
    credential_provider: CredentialProvider | None = None,
    transport: Transport | None = None,
    repository_root: Path | None = None,
) -> dict[str, str | int]:
    """Capture stable raw and structured evidence outside the repository.

    A single retry is allowed when the document revision changes while content
    is being read. No output is created until one complete, stable snapshot is
    available in memory.
    """
    destination = Path(output_dir)
    effective_repository_root = repository_root or _repository_root_from_module()
    if effective_repository_root is not None:
        reject_repository_output(destination, effective_repository_root)
    use_credentials = credential_provider or _environment_credentials
    use_transport = transport or standard_transport

    for _ in range(2):
        headers, document_id, title, revision_id = _resolve_docx(
            wiki_url, use_credentials, use_transport
        )
        raw_content = _raw_content(use_transport, headers, document_id)
        blocks = _blocks(use_transport, headers, document_id, revision_id)
        _, revision_after = _document_metadata(use_transport, headers, document_id)
        if revision_after != revision_id:
            continue

        raw_bytes = raw_content.encode("utf-8")
        blocks_bytes = _canonical_json_bytes(blocks)
        manifest_core: dict[str, str | int | Mapping[str, str]] = {
            "schema_version": "fde-feishu-wiki-evidence-v1",
            "title": title,
            "revision_id": revision_id,
            "retrieved_at": datetime.now(timezone.utc).isoformat(),
            "raw_sha256": _sha256(raw_bytes),
            "blocks_sha256": _sha256(blocks_bytes),
            "representation": {"raw": "plain_text", "blocks": "structured"},
        }
        manifest = {
            **manifest_core,
            "manifest_sha256": _sha256(_canonical_json_bytes(manifest_core)),
        }
        _write_capture(destination, raw_content, blocks, manifest)
        return {
            "status": "CAPTURED",
            "title": title,
            "revision_id": revision_id,
            "raw_sha256": manifest_core["raw_sha256"],
            "blocks_sha256": manifest_core["blocks_sha256"],
            "manifest_sha256": manifest["manifest_sha256"],
        }

    raise EvidenceError("DOCUMENT_CHANGED")


def _is_sha256(value: object) -> bool:
    if not isinstance(value, str) or len(value) != 64:
        return False
    return all(character in "0123456789abcdef" for character in value)


def _manifest_summary(manifest_path: Path) -> dict[str, str | int | Mapping[str, str]] | None:
    try:
        manifest = _require_mapping(json.loads(manifest_path.read_text(encoding="utf-8")))
        if (
            set(manifest) != MANIFEST_FIELDS
            or manifest.get("schema_version") != MANIFEST_SCHEMA_VERSION
        ):
            return None
        manifest_hash = manifest.get("manifest_sha256")
        manifest_core = {
            key: value for key, value in manifest.items() if key != "manifest_sha256"
        }
        if not _is_sha256(manifest_hash) or manifest_hash != _sha256(
            _canonical_json_bytes(manifest_core)
        ):
            return None

        title = manifest.get("title")
        revision_id = manifest.get("revision_id")
        retrieved_at = manifest.get("retrieved_at")
        raw_sha256 = manifest.get("raw_sha256")
        blocks_sha256 = manifest.get("blocks_sha256")
        representation = manifest.get("representation")
        if (
            not isinstance(title, str)
            or not title
            or not isinstance(revision_id, int)
            or isinstance(revision_id, bool)
            or not isinstance(retrieved_at, str)
            or not retrieved_at
            or not _is_sha256(raw_sha256)
            or not _is_sha256(blocks_sha256)
            or representation != {"raw": "plain_text", "blocks": "structured"}
        ):
            return None
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, EvidenceError):
        return None
    return {
        "title": title,
        "revision_id": revision_id,
        "retrieved_at": retrieved_at,
        "raw_sha256": raw_sha256,
        "blocks_sha256": blocks_sha256,
        "manifest_sha256": manifest_hash,
        "representation": representation,
    }


def compare_manifests(left: Path, right: Path) -> dict[str, object]:
    """Compare two local, integrity-checked capture manifests without network I/O."""
    left_summary = _manifest_summary(Path(left))
    right_summary = _manifest_summary(Path(right))
    if left_summary is None or right_summary is None:
        return {"status": "INCOMPLETE"}
    status = (
        "MATCH"
        if (
            left_summary["raw_sha256"] == right_summary["raw_sha256"]
            and left_summary["blocks_sha256"] == right_summary["blocks_sha256"]
        )
        else "DIFFERENT"
    )
    return {"status": status, "left": left_summary, "right": right_summary}


class SafeArgumentParser(argparse.ArgumentParser):
    """Suppress argparse diagnostics because argv values may be sensitive."""

    def error(self, message: str) -> None:
        raise EvidenceError("INVALID_ARGUMENTS")


def _build_argument_parser() -> argparse.ArgumentParser:
    parser = SafeArgumentParser(description="Read-only Feishu Wiki evidence collector")
    commands = parser.add_subparsers(
        dest="command", required=True, parser_class=SafeArgumentParser
    )
    for name in ("probe", "capture"):
        command = commands.add_parser(name)
        command.add_argument("--wiki-url", required=True)
        if name == "capture":
            command.add_argument("--output-dir", required=True)
    compare = commands.add_parser("compare")
    compare.add_argument("--left", required=True)
    compare.add_argument("--right", required=True)
    return parser


def _emit(payload: Mapping[str, object]) -> None:
    print(json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")))


def _probe_stdout(result: Mapping[str, str | int]) -> dict[str, str | int]:
    return {
        "status": "PROBED",
        "title": result["title"],
        "revision_id": result["revision_id"],
    }


def main(
    argv: list[str] | None = None,
    *,
    credential_provider: CredentialProvider | None = None,
    transport: Transport | None = None,
) -> int:
    """Run a deliberately narrow CLI whose stdout excludes secrets and content."""
    try:
        arguments = _build_argument_parser().parse_args(argv)
    except EvidenceError as error:
        _emit({"status": "ERROR", "error": error.code})
        return 1
    except SystemExit as error:
        return int(error.code) if isinstance(error.code, int) else 2

    try:
        if arguments.command == "probe":
            _emit(
                _probe_stdout(
                    probe(
                        arguments.wiki_url,
                        credential_provider=credential_provider,
                        transport=transport,
                    )
                )
            )
            return 0
        if arguments.command == "capture":
            output_dir = Path(arguments.output_dir)
            if not output_dir.is_absolute():
                raise EvidenceError("OUTPUT_PATH_REJECTED")
            _emit(
                capture(
                    arguments.wiki_url,
                    output_dir,
                    credential_provider=credential_provider,
                    transport=transport,
                )
            )
            return 0
        if arguments.command == "compare":
            _emit(compare_manifests(Path(arguments.left), Path(arguments.right)))
            return 0
        raise EvidenceError("COMMAND_REJECTED")
    except EvidenceError as error:
        _emit({"status": "ERROR", "error": error.code})
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""W-A VIEW 看板 · GET /api/platform/rsi-fde (read-only RSI+FDE control-plane view).

The "可感知" headline for the perceivable control plane: ONE read that answers
"is the living system alive?" — FDE verdicts flowing (external buyer acceptance =
the only fitness that escapes the self-referential internal economy), agents
present (by survival status), platform_external_events streaming, plus a
PoI-eligibility summary DERIVED from passed verdicts.

Boundaries honored:
  - G-turf · the PoI summary is derived platform-side from fde_verdicts. It does
    NOT read compass PoI internals — it reports what FEEDS PoI (passed verdicts),
    not compass's ledger.
  - anchor #3 · deliberately does NOT touch pending_nau_rewards / votes (the
    self-referential signals the benchmark pivot moved away from).

Fail-soft per section: a missing table yields an empty section, never a 500, so
the same endpoint renders against the sqlite test fixture and the postgres
production target. Mirrors api/soul_activity.py raw-SQL conventions.
"""
